export const CHAPTERS=[
 {id:'task',n:'1',title:'Завдання та вихідні дані',intro:'Задайте потрібний момент і частоту обертання робочого вала для будь-якого механізму. Якщо навантаження задане коловою силою та лінійною швидкістю, оберіть відповідний спосіб задання. Визначте склад привода та критерії перевірки; параметри двигуна прийміть у розділі 2.',source:'de'},
 {id:'power',n:'2',title:'Кінематика, потужність і момент',intro:'Передатні числа визначають швидкість, ККД — втрати, а потужність і частота обертання — момент. Перевіряйте фактичну швидкість після прийняття цілих чисел зубців.',source:'ha'},
 {id:'flex',n:'3',title:'Паси, зубчасті паси та ланцюги',intro:'Гнучка передача розміщується між двигуном і редуктором. Звичайний пас враховує ковзання; зубчастий пас і ланцюг — дискретний крок та число зубців. Оберіть тип у розділі 1.',source:'gates'},
 {id:'gears',n:'4',title:'Зубчасті передачі',intro:'Геометрія обраного типу редуктора: кут профілю 20°, зміщення x = 0; нормальний модуль для циліндричної та черв’ячної передачі, зовнішній — для прямозубої конічної. Числа зубців приймають цілими.',source:'khk'},
 {id:'strength',n:'5',title:'Згин зубців і контакт',intro:'Навчальні перевірки згину з введеним коефіцієнтом форми та локального пружного контакту Герца. Допустимі напруження і коефіцієнти є прийнятими даними; повний розрахунок за ISO 6336 потребує додаткових факторів.',source:'ha'},
 {id:'shaft',n:'6',title:'Тихохідний вал',intro:'Круглий суцільний вал на двох шарнірних опорах; колесо між опорами, вихідна муфта передає лише крутний момент. Перевіряються статичні напруження, прогин у місці колеса та кут закручування.',source:'ba'},
 {id:'bearings',n:'7',title:'Підшипники кочення',intro:'Прямозубе зачеплення не створює осьового зусилля. Для цього випадку еквівалентне навантаження дорівнює радіальній реакції. Оберіть відкритий кульковий підшипник SKF зі спільного CSV або введіть власні каталожні дані. Список містить сумісні з шийками та навантаженням варіанти. Перевіряються міцність шийок, базовий ресурс, статичний запас, номінальний отвір, ширина й гранична частота.',source:'skf'},
 {id:'key',n:'8',title:'Шпонка та вихідна муфта',intro:'Призматична шпонка із заокругленими торцями: робоча довжина lₑ = l − b. Зминання і зріз перевіряються окремо. Муфта перевіряється за введеним допустимим моментом.',source:'ro'},
 {id:'bolts',n:'9',title:'Болтове з’єднання',intro:'Окремий приклад попередньо затягнутого з’єднання: однакові болти, рівномірне навантаження без ексцентриситету. Частку зовнішнього осьового навантаження χ задають за жорсткістю болта та деталей.',source:'st'},
 {id:'basics',n:'10',title:'Базові розрахунки деталей',intro:'Окремі задачі: осьове розтягування стрижня та циліндрична пружина стиску. Лінійно-пружний матеріал, малі деформації; для пружини — круглий дріт та індекс D/d ≥ 4.',source:'ha'},
 {id:'comparison',n:'11',title:'Порівняння та обґрунтування',intro:'Зафіксуйте базовий варіант, змініть параметри та зіставте результати. Порівняння має сенс за однакових вимог робочої машини. Поясніть прийняті компроміси.',source:'de'},
 {id:'sources',n:'',title:'Джерела',intro:'Кожне джерело має визначену роль. Старі нормативні посилання в підручниках не трактуються як підтвердження чинності стандартів. Нормативні та каталожні дані для конкретного виробу перевіряються окремо.'}
];

