export function active(item,inputs,mode){const type=item.stage?stageType(inputs,item.stage):null;return (!item.gearTypes||item.gearTypes.includes(type))&&(!item.combinedOnly||inputs.gearboxType===4)&&(!item.axialOnly||stageType(inputs,inputs.stages)!==0||inputs['beta'+inputs.stages]!==0)&&(inputs.basicLimitMode!==0||!['rodStrength','rodSafety','springStrength','springSafety','rodFactor','springFactor'].includes(item.key||item.id))&&(inputs.basicLimitMode===0||!['rodAllow','springAllow'].includes(item.key))&&(!item.stage||item.stage<=inputs.stages)&&(!item.mode||item.mode===mode)&&(item.taskKind===undefined||item.taskKind===inputs.taskKind)&&(item.key!=='shaftAllow'||inputs.shaftMaterial===0)&&(item.id!=='shaftFactor'||inputs.shaftMaterial!==0)&&(!item.internal||['A_t','A_ch','I_s','J_s'].includes(item.id));}
export function selectionExpressions(mode,taskKind=0,shaftMaterial=1,basicLimitMode=1,inputs=null){return {...(inputs?gearboxExpressions(inputs):{}),rodLimit:basicLimitMode?'R_rod/n_rod':'S_rod',springLimit:basicLimitMode?'R_sp/n_sp':'tau_sp',u_ext:{none:'1',belt:'u_b',timing:'u_t',chain:'u_ch'}[mode],eta_ext:{none:'1',belt:'eta_b',timing:'eta_t',chain:'eta_ch'}[mode],P_req:taskKind===0?'2*pi*T_req*n_target':'F*v',n_req:taskKind===0?'n_target':'v/(pi*D)',shaftLimit:shaftMaterial===0?'S_s':'R_e/n_s'};}
